INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ca_notary', 'Notary', 'CA', 'California Notary', 1, 1, 45, 3600, 70, 32, '45 questions / 60 minutes / scaled score of 70 to pass, per CPS HR''s official exam FAQ. The real score is a proprietary scaled score (0-100), not literally percent-correct -- this uses raw percent-correct against the same 70 threshold as a practice approximation.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ca_driver', 'Driver', 'CA', 'California Driver', 1, 1, 36, 0, 83.3, 30, 'The real CA DMV Class C written knowledge test''s format depends on the applicant''s age -- confirmed against DMV''s own 2006 Class C written-test evaluation report plus current (2026) corroborating sources: first-time applicants 18+ get 36 questions (30 correct/83.3% to pass), first-time applicants under 18 (provisional permit) get 46 questions (38 correct/82.6%). This entry is the 18+ format -- the default for anyone who didn''t give an age at checkout or pick a category on the exam intro page (see CA_DRIVER_UNDER18_CONFIG + getExamConfig below). 30/36 = 83.33...%, using 83.3 (not 83) so a candidate scoring exactly the real pass line is graded as passing here too, same reasoning as the under-18 variant''s 82.6. The real test is genuinely untimed (in-person at a DMV office/kiosk, confirmed against DMV''s own testing-process page and that same evaluation report -- no time limit is mentioned anywhere). durationSec: 0 is this codebase''s sentinel for "untimed" -- every consumer (findInProgressAttempt, handleExamAnswer, buildExamResult) treats a falsy duration_sec as "never expires" rather than computing against it.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ca_cdl', 'Commercial Driver (CDL)', 'CA', 'California CDL', 1, 1, 50, 3600, 80, 40, '50 questions / 40 correct (80%) to pass, per the real CA DMV CDL General Knowledge test -- the one test every CDL candidate takes regardless of endorsements. The question bank also covers Air Brakes/Combination Vehicles and Passenger/School Bus/Tank/HazMat endorsement content (real candidates only take the specific endorsement tests they need, as separate sittings) -- this mock exam blends everything into one practice sitting rather than modeling each real sub-test separately, same simplification as the hub card''s combined breakdown. Untimed in reality (in-person at a DMV office/kiosk); 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ca_motorcycle', 'Motorcycle', 'CA', 'California Motorcycle', 1, 1, 25, 3600, 80, 20, '25 questions / 20 correct (80%) to pass, per the real CA DMV M1/M2 motorcycle written knowledge test. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('tx_driver', 'Driver', 'TX', 'Texas Driver', 1, 1, 30, 3600, 70, 21, '30 questions / 21 correct (70%) to pass, per the real Texas DPS driver knowledge test. Untimed in reality (in-person at a DPS office/kiosk); 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('tx_cdl', 'Commercial Driver (CDL)', 'TX', 'Texas CDL', 1, 1, 50, 3600, 80, 40, '50 questions / 40 correct (80%) to pass, per the real Texas DPS CDL General Knowledge test -- same AAMVA-standard format as ca_cdl. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('fl_driver', 'Driver', 'FL', 'Florida Driver', 1, 1, 50, 3600, 80, 40, '50 questions / 40 correct (80%) to pass, per the real FLHSMV Class E Knowledge Exam. Untimed in reality (in-person at a FLHSMV office/kiosk); 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('fl_cdl', 'Commercial Driver (CDL)', 'FL', 'Florida CDL', 1, 1, 50, 3600, 80, 40, '50 questions / 40 correct (80%) to pass, per the real FLHSMV CDL General Knowledge test -- same AAMVA-standard format as ca_cdl/tx_cdl. 1 hour time limit in reality, matches durationSec.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ny_driver', 'Driver', 'NY', 'New York Driver', 1, 1, 20, 3600, 70, 14, '20 questions / 14 correct (70%) to pass, per the real NY DMV Class D written knowledge test. Untimed in reality (in-person at a DMV office/kiosk); 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ny_cdl', 'Commercial Driver (CDL)', 'NY', 'New York CDL', 1, 1, 50, 3600, 80, 40, '50 questions / 40 correct (80%) to pass, per the real NY DMV CDL General Knowledge test -- same AAMVA-standard format as ca_cdl/tx_cdl/fl_cdl. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ny_notary', 'Notary', 'NY', 'New York Notary', 1, 1, 40, 3600, 70, 28, '40 questions / 28 correct (70%) to pass, per the real NY Department of State notary exam FAQ. Genuinely timed in reality (60 minutes), unlike the untimed DMV tests above.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('il_driver', 'Driver', 'IL', 'Illinois Driver', 1, 1, 35, 3600, 80, 28, '35 questions / 28 correct (80%) to pass, per the real Illinois Secretary of State Class D written knowledge test (confirmed via actual state regulation, not just secondary sources). Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('il_real_estate', 'Real Estate Salesperson', 'IL', 'Illinois Real Estate', 1, 1, 40, 3600, 75, 30, 'State-specific portion only (not the national/general portion -- see project notes): 40 questions / 75% to pass (30/40 correct exactly), per the PSI Candidate Information Booklet for the IDFPR Broker exam. Genuinely timed in reality (90 minutes for this portion).', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('il_managing_broker', 'Real Estate Broker', 'IL', 'Illinois Managing Broker', 1, 1, 50, 3600, 75, 38, 'State-specific only (this exam has no national portion at all): 50 questions / 75% to pass, per the same PSI Candidate Information Booklet''s Managing Broker Examination Summary Table. Genuinely timed in reality (90 minutes).', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('pa_driver', 'Driver', 'PA', 'Pennsylvania Driver', 1, 1, 18, 3600, 83.3, 15, '18 questions / 15 correct to pass, per the real PennDOT non-commercial knowledge test. 15/18 = 83.3% (buildExamResult rounds percent to 1 decimal) -- using 83.3, not 83, so a candidate scoring exactly the real pass line is graded as passing here too. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('pa_cdl', 'Commercial Driver (CDL)', 'PA', 'Pennsylvania CDL', 1, 1, 50, 3600, 80, 40, '50 questions / 40 correct (80%) to pass -- PennDOT''s own fact sheet doesn''t state a pass score, but 80% is the FEDERAL minimum under 49 CFR 383.135(a), binding on every state''s CDL knowledge test (confirmed at ecfr.gov), same AAMVA-standard format as every other CDL track. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('pa_real_estate', 'Real Estate Salesperson', 'PA', 'Pennsylvania Real Estate', 1, 1, 40, 3600, 75, 30, 'State-specific portion only (not the national/general portion -- see project notes): 40 questions / 75% to pass (30/40 correct exactly), per the Pearson VUE Candidate Handbook for the PA Real Estate Salesperson exam. Genuinely timed in reality (60 minutes for this portion).', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ca_real_estate', 'Real Estate Salesperson', 'CA', 'California DRE', 1, 1, 150, 11700, 70, 105, '150 questions / 105 correct (70%) to pass, per the real DRE Salesperson exam -- covers both the national/general and state-specific content in one unified test (DRE administers its own exam directly, no PSI/Pearson national-vs-state split like other states'' real estate tracks). Genuinely timed in reality: 3 hours 15 minutes (11700 sec), not a stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('oh_driver', 'Driver', 'OH', 'Ohio Driver', 1, 1, 40, 3600, 75, 30, '40 questions / 30 correct (75%) to pass, per the real Ohio BMV driver knowledge test (confirmed via bmv.ohio.gov plus corroborating secondary sources). No official time limit is published; untimed in reality (in-person at a BMV kiosk). 60 minutes is a generous stand-in, same treatment as tx_driver/fl_driver/ny_driver/il_driver/pa_driver above.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('oh_cdl', 'Commercial Driver (CDL)', 'OH', 'Ohio CDL', 1, 1, 50, 3600, 80, 40, '50 questions / 40 correct (80%) to pass, per the real Ohio BMV CDL General Knowledge test -- same AAMVA-standard format as every other CDL track above. Genuinely timed in reality (60 minutes), confirmed via multiple corroborating sources -- matches durationSec here, not a stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('oh_motorcycle', 'Motorcycle', 'OH', 'Ohio Motorcycle', 1, 1, 40, 3600, 75, 30, '40 questions / 30 correct (75%) to pass, per the real Ohio BMV motorcycle written knowledge test -- same computer-kiosk test mechanism as oh_driver, no official time limit published. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('oh_real_estate', 'Real Estate Salesperson', 'OH', 'Ohio Real Estate', 1, 1, 40, 3600, 70, 28, 'State-specific portion only (not the national/general portion -- see project notes): 40 questions / 28 correct (70%) to pass, per the real PSI Candidate Information Bulletin''s Examination Summary Table, independently confirmed by OAC 1301:5-1-05(E). Genuinely timed in reality (60 minutes for this portion) -- matches durationSec, not a stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('oh_boating', 'Boating', 'OH', 'Ohio Boating', 1, 1, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass -- the common format across the NASBLA/ODNR-approved course vendors checked (BOATERexam/AceBoater use 60Q covering all 9 handbook chapters; 80% is consistent everywhere including BOATsmart!, which uses a 50Q variant of the same test). No single official Ohio boating exam exists -- see oh_boating''s TRACK_COMPLIANCE entry for the full disclosure. No time limit published anywhere; untimed in reality (self-paced course).', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ga_driver', 'Driver', 'GA', 'Georgia Driver', 1, 1, 40, 3600, 75, 30, 'The real DDS test is actually two independently-graded 20-question sections (Road Rules, Road Signs), each requiring 15/20 (75%), confirmed directly from dds.georgia.gov -- built as a single unified 40Q/75% practice exam anyway (disclosed simplification, see ga_driver''s TRACK_COMPLIANCE entry). No time limit published; untimed in reality (in-person DDS kiosk).', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ga_cdl', 'Commercial Driver (CDL)', 'GA', 'Georgia CDL', 1, 1, 50, 3600, 80, 40, '50 questions / 40 correct (80%) to pass -- the same AAMVA-standard CDL General Knowledge format as every other state''s CDL track. Untimed in reality; 60 minutes is a generous stand-in, same treatment as most other CDL tracks above.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ga_motorcycle', 'Motorcycle', 'GA', 'Georgia Motorcycle', 1, 1, 25, 1800, 80, 20, '25 questions / 20 correct (80%) to pass, 30-minute limit -- picked the internally-consistent figure (20/25 is an exact 80%, corroborated with this specific time limit) over a competing "75%" claim from other secondary sources that doesn''t divide evenly into 25.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ga_real_estate', 'Real Estate Salesperson', 'GA', 'Georgia Real Estate', 1, 1, 52, 7200, 75, 39, 'State-specific portion only (not the national/general portion -- see project notes): 52 questions / 39 correct (75%) to pass, per the real PSI Candidate Information Bulletin -- confirmed via multiple corroborating sources. Genuinely timed in reality (2 hours for a state-portion-only sitting) -- matches durationSec, not a stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('nc_driver', 'Driver', 'NC', 'North Carolina Driver', 1, 1, 37, 3600, 78.4, 29, 'The real NC DMV test is actually two components: a 25-question general knowledge test (20/25, 80%) plus a 12-item road-sign identification test (9/12, 75%) -- confirmed via ncdot.gov. Built as a single unified 37Q practice exam (25+12), blended pass threshold 29/37 (78.4%), same disclosed-simplification pattern as ga_driver. No time limit published; untimed in reality.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('nc_cdl', 'Commercial Driver (CDL)', 'NC', 'North Carolina CDL', 1, 1, 50, 3600, 80, 40, '50 questions / 40 correct (80%) to pass -- same AAMVA-standard CDL General Knowledge format as every other state''s CDL track. Genuinely timed in reality (60 minutes).', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('nc_real_estate', 'Real Estate Salesperson', 'NC', 'North Carolina Real Estate', 1, 1, 60, 7200, 75, 45, 'State-specific portion only (not the national/general portion): 60 questions / 45 correct (75%) to pass, per the current (April 2026) PSI/Pearson VUE Candidate Handbook''s weighted state outline, corroborated by NCREC''s own License Law and Rules Comments. Genuinely timed in reality (2 hours for this portion).', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('nc_notary', 'Notary', 'NC', 'North Carolina Notary', 1, 1, 50, 3600, 80, 40, '50 questions / 40 correct (80%) to pass -- a real statutory threshold, NC General Statutes Chapter 10B (the Notary Public Act) section 10B-8, fetched fresh from ncleg.gov. Untimed; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('nc_boating', 'Boating', 'NC', 'North Carolina Boating', 1, 1, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass, grounded in the NC Vessel Operator''s Guide -- same "clean free content, minor provider-format variance" pattern as oh_boating. Untimed in reality.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('va_driver', 'Driver', 'VA', 'Virginia Driver', 1, 1, 40, 3600, 85, 34, 'The real VA DMV test has a two-gate structure: Part 1 is 10 road-sign questions requiring ALL 10 correct (confirmed directly from dmv.virginia.gov -- no partial credit), Part 2 is 30 general-knowledge questions at 80% (24/30). Built as a single unified 40Q practice exam, blended pass threshold 34/40 (85%) -- disclosed simplification, same pattern as ga_driver/ nc_driver. Untimed in reality.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('va_cdl', 'Commercial Driver (CDL)', 'VA', 'Virginia CDL', 1, 1, 50, 3600, 80, 40, '50 questions / 40 correct (80%) to pass -- same AAMVA-standard CDL General Knowledge format. Genuinely timed in reality (60 minutes).', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('va_motorcycle', 'Motorcycle', 'VA', 'Virginia Motorcycle', 1, 1, 25, 3600, 80, 20, '25 questions / 20 correct (80%) to pass, per the VA Motorcycle Rider''s Manual''s own published question count. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('va_real_estate', 'Real Estate Salesperson', 'VA', 'Virginia Real Estate', 1, 1, 40, 2700, 75, 30, 'State-specific portion only: 40 questions / 30 correct (75%) to pass, per the real weighted PSI outline (Licensing 8, Escrow Accounts 2, Disclosure Requirements 10, Agency Definitions/ Relationships 12, VA Fair Housing 4, Specific Acts 4 -- sums to 40). Genuinely timed in reality (45 minutes).', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('va_boating', 'Boating', 'VA', 'Virginia Boating', 1, 1, 75, 3600, 80, 60, '75 questions / 60 correct (80%) to pass -- codified directly in Virginia Administrative Code 4VAC15-410, a single DWR-administered equivalency exam (no free PDF handbook exists; content was web-scraped from the DWR Boater''s Guide site directly). Untimed in reality.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('mi_driver', 'Driver', 'MI', 'Michigan Driver', 1, 1, 50, 3600, 80, 40, '50 questions / 40 correct (80%) to pass, per the Michigan Driver''s Manual (Secretary of State, Oct 2025 edition). Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('mi_cdl', 'Commercial Driver (CDL)', 'MI', 'Michigan CDL', 1, 1, 50, 3600, 80, 40, '50 questions / 40 correct (80%) to pass -- same AAMVA-standard CDL General Knowledge format. Genuinely timed in reality (~60 minutes).', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('mi_motorcycle', 'Motorcycle', 'MI', 'Michigan Motorcycle', 1, 1, 25, 3600, 80, 20, '25 questions / 20 correct (80%) to pass, per the Michigan Motorcycle Operator Manual (May 2022 edition, still the current version linked from michigan.gov/sos). Untimed in reality.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('mi_boating', 'Boating', 'MI', 'Michigan Boating', 1, 1, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass, Kalkomey-produced and DNR-promoted -- same provider-administered pattern as oh_boating/nc_boating. Untimed in reality.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ca_boating', 'Boating', 'CA', 'California Boating', 1, 1, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass -- DBW approves third-party NASBLA-standard courses (Boat-Ed, ACE Boater, etc.) rather than administering one single exam; this format converges consistently across DBW-approved providers. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('tx_boating', 'Boating', 'TX', 'Texas Boating', 1, 1, 75, 3600, 80, 60, '75 questions / 60 correct (80%) to pass -- hedged, TPWD approves third-party vendor courses whose item counts genuinely vary 50-75 by provider (a TPWD-affiliated classroom course uses 60); this uses the most-cited national-vendor (Boat-Ed/BOATERexam) format. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('fl_boating', 'Boating', 'FL', 'Florida Boating', 1, 1, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass -- FWC approves third-party NASBLA-standard courses (Boat-Ed, BOATERexam, etc.) rather than administering one single exam; this format converges tightly across FWC-approved providers. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ny_boating', 'Boating', 'NY', 'New York Boating', 1, 1, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass -- hedged, item counts genuinely vary 50-60 by OPRHP-approved vendor and passing scores converge mostly in the 75-80% range; this uses the upper-end round figure. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('pa_boating', 'Boating', 'PA', 'Pennsylvania Boating', 1, 1, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass -- PFBC-approved vendors (Boat-Ed, Aceboater, etc.) converge tightly on this format rather than PFBC administering one single exam. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('il_boating', 'Boating', 'IL', 'Illinois Boating', 1, 1, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass -- hedged, IDNR''s handbook directs boaters to Boat-Ed (confirmed 80% passing, unlimited retakes) but the exact per-vendor question count is not publicly published; 60q matches the industry-wide 50-60 range reported for NASBLA course finals. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ga_boating', 'Boating', 'GA', 'Georgia Boating', 1, 1, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass -- CONFIRMED convergence: Boat-Ed (the provider GA DNR''s handbook directs boaters to) confirms 80% passing with unlimited retakes, and BoatUS Foundation''s Georgia course independently confirms 60 final-exam questions. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('nj_boating', 'Boating', 'NJ', 'New Jersey Boating', 1, 1, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass, CONFIRMED live on NJSP''s FAQ and boat-ed.com/newjersey for the NASBLA-approved online course''s final exam (unit quizzes separately require 70%, unlimited attempts). This is NOT the separate mandatory in-person proctored NJSP exam, whose question count/passing score NJSP does not publicly publish. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('wa_boating', 'Boating', 'WA', 'Washington Boating', 1, 1, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass -- CONFIRMED convergence: Boat-Ed confirms 80% passing on its final exam (70% on unit quizzes, unlimited retakes), and BoatUS Foundation''s Washington course independently confirms 60 final-exam questions. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('az_boating', 'Boating', 'AZ', 'Arizona Boating', 1, 0, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass -- unconfirmed stand-in. Arizona has NO mandatory boater-education law (confirmed via ARS Title 5 Ch.3 and 2 AZGFD-approved vendor pages stating outright "not required in Arizona"); this format applies only to boaters who voluntarily take an AZGFD-approved course. Boat-Ed and iLearnToBoat both confirm 80% passing, but neither publishes an exact question count. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ma_boating', 'Boating', 'MA', 'Massachusetts Boating', 1, 1, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass -- hedged, neither MEP-approved vendor (Boat-Ed, iLearnToBoat) publishes an official final-exam item count, though both independently confirm 80% passing with unlimited retakes. Untimed in reality; 60 minutes is a generous stand-in. Massachusetts''s boater education mandate is a new, currently phasing-in law (certify by April 2026 or April 2028 depending on birth date) -- see ma_boating''s TRACK_COMPLIANCE entry for full disclosure.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('tn_boating', 'Boating', 'TN', 'Tennessee Boating', 1, 1, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass -- hedged, TWRA does not publish an item count for its own delegated exam, but the independently TWRA-approved Boat-Ed course confirms 80% final-exam passing (70% on unit quizzes) with unlimited retakes. Untimed in reality; 60 minutes is a generous stand-in. TWRA directly administers its own proctored exam pathway ($13 Type 600 permit) alongside the separate paid Boat-Ed course -- see tn_boating''s TRACK_COMPLIANCE entry for both paths.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('mo_boating', 'Boating', 'MO', 'Missouri Boating', 1, 1, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass -- hedged, Missouri''s approved vendors don''t consistently publish a final-exam item count, but Boat-Ed''s official Missouri course confirms 80% final-exam passing (70% on unit quizzes) with unlimited retakes. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('md_boating', 'Boating', 'MD', 'Maryland Boating', 1, 1, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass -- hedged, Maryland''s approved vendors don''t publish a single official item count, but Boat-Ed''s Maryland course confirms 80% final-exam passing with unlimited retakes. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('sc_boating', 'Boating', 'SC', 'South Carolina Boating', 1, 1, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass -- hedged, South Carolina''s approved vendors don''t consistently publish a final-exam item count, but Boat-Ed''s official South Carolina course confirms 80% final-exam passing (70% on unit quizzes) with unlimited retakes. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('mn_boating', 'Boating', 'MN', 'Minnesota Boating', 1, 1, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass -- fully hedged self-study convention. Minnesota''s mandate (Minn. Stat. 86B.302) is confirmed and genuinely phasing in through 2028, but neither the DNR nor its approved course vendors uniformly publish a final-exam question count or passing percentage. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('wi_boating', 'Boating', 'WI', 'Wisconsin Boating', 1, 1, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass -- 80% passing threshold CONFIRMED (two independent DNR-approved vendors, Boat-Ed and iLearnToBoat, both require 80%+ on the final exam); the 60-question count is hedged, since no vendor consistently publishes an exact figure. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('al_boating', 'Boating', 'AL', 'Alabama Boating', 1, 1, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass -- 80% final-exam threshold CONFIRMED directly on Boat-Ed''s Alabama course page (after 70%+ unit quizzes); question count hedged, not published by ALEA or Boat-Ed. Alabama also offers a separate ALEA-administered state exam as an alternate path with an unpublished format. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('la_boating', 'Boating', 'LA', 'Louisiana Boating', 1, 1, 60, 3600, 80, 48, '60 questions (CONFIRMED via BoatUS.org''s Louisiana course) / 48 correct (80%, CONFIRMED via Boat-Ed''s final-exam threshold) to pass -- LDWF''s own in-person course uses a separately confirmed, different 70% threshold; this config matches the most convergent online-vendor figures, not one official LDWF-wide number. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('nv_boating', 'Boating', 'NV', 'Nevada Boating', 1, 1, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass -- 80% threshold CONFIRMED directly on Boat-Ed''s Nevada course page (both unit quizzes and final exam); question count hedged, not consistently published across NDOW-approved vendors. NRS 488.730''s mandate applies specifically to Nevada''s interstate boundary waters (Tahoe/Mead/Mohave), not a blanket statewide rule. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ct_boating', 'Boating', 'CT', 'Connecticut Boating', 1, 1, 60, 3600, 80, 48, '60 questions / 48 correct (80%) to pass -- fully hedged self-study convention matching DEEP''s own confirmed Equivalency Examination passing threshold (80%, $75 fee, one attempt). Connecticut''s mandate is registration/residency-based, not birth-date-based, and its 9-provider approved-course landscape has no published cross-vendor convergence on a standard question count or score. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('mi_real_estate', 'Real Estate Salesperson', 'MI', 'Michigan Real Estate', 1, 1, 40, 2700, 70, 28, 'Michigan''s real Salesperson exam is ONE unified 115-question/70%/180min sitting with NO separate state-only portion (confirmed: no national/state labels anywhere in the PSI bulletin, unlike every other state built so far). MI-specific content is a real, PSI-weighted 28-item scope (Duties/Powers 3, Licensing 5, Statutory Requirements 10, Contractual Relationships 5, Additional State Topics 5) grounded in MCL 339.2501-2518 -- but no official practice-exam size/ pass threshold exists for this supplemental scope alone, since it was never meant to be taken standalone. 40Q/70%/45min chosen here as a reasonable practice-test sizing (matches this project''s default real-estate pass threshold elsewhere, e.g. oh_real_estate) -- an explicit product decision, not a sourced number. TRACK_COMPLIANCE frames this honestly as "Michigan-specific subject matter," never as "the state portion of the exam."', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('wa_driver', 'Driver', 'WA', 'Washington Driver', 1, 1, 40, 3600, 80, 32, '40 questions / 32 correct (80%) to pass, officially published on dol.wa.gov. No official time limit found; untimed in reality, 60 minutes is a generous stand-in per this project''s convention.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('wa_cdl', 'Commercial Driver (CDL)', 'WA', 'Washington CDL', 1, 1, 50, 3600, 80, 40, '50 questions / 40 correct (80%) to pass -- same AAMVA-standard CDL General Knowledge format. Genuinely timed in reality (60 minutes).', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('wa_motorcycle', 'Motorcycle', 'WA', 'Washington Motorcycle', 1, 1, 25, 3600, 80, 20, 'WA licensing is two-tier: a 50Q/80% Permit test, then a 25Q/80% Endorsement test after permit holding. This track models the Endorsement (full-license) tier -- 25Q/80% -- matching the question count/format used by every other state''s motorcycle track built this project. Both counts officially published on dol.wa.gov; neither has a published time limit.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('al_motorcycle', 'Motorcycle', 'AL', 'Alabama Motorcycle', 1, 1, 30, 3600, 80, 24, '30 questions / 24 correct (80%) to pass -- hedged, not officially disclosed by ALEA; matches the 5 convergent third-party sources checked and AL''s separate Driver track''s own hedge. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ar_motorcycle', 'Motorcycle', 'AR', 'Arkansas Motorcycle', 1, 1, 25, 3600, 80, 20, '25 questions / 20 correct (80%) to pass -- hedged, not officially disclosed anywhere by AR DPS; matches 3 convergent third-party sources. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ct_motorcycle', 'Motorcycle', 'CT', 'Connecticut Motorcycle', 1, 1, 16, 3600, 80, 13, '16 questions confirmed directly from the manual ("consist of 16 questions") and portal.ct.gov. Passing score hedged -- not published anywhere official; 80% (13 correct) used as the standard stand-in. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('mn_motorcycle', 'Motorcycle', 'MN', 'Minnesota Motorcycle', 1, 1, 40, 3600, 80, 32, '40 questions / 32 correct (80%) to pass -- hedged, the manual''s own preface confirms the test is mandatory for everyone but no official item count/passing % is published; matches convergent third-party sources. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ms_motorcycle', 'Motorcycle', 'MS', 'Mississippi Motorcycle', 1, 1, 25, 3600, 80, 20, '25 questions / 20 correct (80%) to pass -- hedged, official MS DPS pages confirm the knowledge test is mandatory (course only waives the skills test) but no item count/passing % is published; matches convergent third-party sources. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('nc_motorcycle', 'Motorcycle', 'NC', 'North Carolina Motorcycle', 1, 1, 25, 3600, 80, 20, '25 questions / 20 correct (80%) to pass -- hedged, official NCDMV confirms the test is mandatory (course only waives skills test) but no item count/passing % is published; 25q/80% is the more consistently-cited third-party figure over a conflicting 37q/78% source. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ny_motorcycle', 'Motorcycle', 'NY', 'New York Motorcycle', 1, 1, 20, 3600, 70, 14, '20 questions / 14 correct (70%) to pass, CONFIRMED directly from NY DMV''s own site (dmv.ny.gov/driver-license/get-a-motorcycle-learner-permit-and-license) -- also requires at least 2 of 4 road-sign questions correct (that sub-requirement is documented in TRACK_COMPLIANCE, not separately modeled here). MSF course waiver applies only to the road/skills test, never the written test. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('pa_motorcycle', 'Motorcycle', 'PA', 'Pennsylvania Motorcycle', 1, 1, 20, 3600, 80, 16, '20 questions / 16 correct (80%) to pass -- hedged, PennDOT confirms the knowledge test is mandatory for all applicants (PAMSP course only waives the skills test) but doesn''t publish an official item count/passing %; matches convergent third-party sources. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('tx_motorcycle', 'Motorcycle', 'TX', 'Texas Motorcycle', 1, 1, 25, 3600, 80, 20, '25 questions / 20 correct (80%) to pass -- hedged, neither TDLR nor DPS publish an official item count/passing %; third-party sources disagree (20q vs 25q, both claiming 80%). Matches the stand-in already used for CA/GA/MI/VA/WA. Untimed in reality; 60 minutes is a generous stand-in. IMPORTANT: most TX applicants waive this written test entirely via a TDLR-approved course -- see tx_motorcycle''s TRACK_COMPLIANCE entry for full disclosure.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ut_motorcycle', 'Motorcycle', 'UT', 'Utah Motorcycle', 1, 1, 25, 3600, 80, 20, '25 questions CONFIRMED directly from two independent dld.utah.gov pages (closed-book test). 80% (20 correct) passing is well-corroborated -- matches UT''s own confirmed Driver-track passing % and third-party sources -- but not stated verbatim by DLD for the motorcycle test specifically, so the percentage is hedged even though the item count is confirmed. Untimed in reality; 60 minutes is a generous stand-in.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('wa_real_estate', 'Real Estate Salesperson', 'WA', 'Washington Real Estate', 1, 1, 30, 5400, 70, 21, 'Washington''s entry-level license is called "Broker" (not "Salesperson"). State-specific portion: 30 items / 70% scaled score / 90min, per the real weighted PSI content outline. Treated as a direct raw passPercent, same resolved convention as nc_real_estate/ga_real_estate''s own scaled-vs-raw ambiguity.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('wa_managing_broker', 'Real Estate Broker', 'WA', 'Washington Managing Broker', 1, 1, 44, 5400, 75, 33, 'Managing Broker is WA''s supervisory upgrade tier (same pattern as il_managing_broker). State portion: 44 items / 75% scaled score / 90min, per the real weighted PSI content outline.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('mlo', 'Mortgage Loan Origination', 'US', 'National MLO', 0, 1, 125, 11400, 75, 94, 'Scaffold track (inactive, no live content) -- mechanics synthesized from its own HUB_EXAMS description (190 min, 125 questions/115 scored, 75% to pass) since it was never wired into EXAM_CONFIGS.', 1788111262);
