INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('wy_driver', 'Driver', 'WY', 'Wyoming Driver', 1, 1, 40, 3600, 80, 32, '', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('al_cdl', 'Commercial Driver (CDL)', 'AL', 'Alabama CDL', 1, 1, 50, 3600, 80, 40, 'Alabama uses the AAMVA CDL Testing System (2005 CDL Testing System manual, ALEA Driver License Division). General Knowledge test is 50 questions / 40 correct (80%) to pass, per FMCSA''s federally standardized 49 CFR 383.135(a) minimum and confirmed via multiple third-party AL CDL prep sources; untimed in person at an ALEA office in reality, 60 minutes is a generous stand-in per this project''s convention.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ak_cdl', 'Commercial Driver (CDL)', 'AK', 'Alaska CDL', 1, 1, 50, 3600, 80, 40, 'Alaska uses the AAMVA CDL Testing System (2005 CDL Testing System manual, rev. AK DMV 02/2018), published by the Alaska Dept. of Administration, Division of Motor Vehicles. The manual states "the minimum passing score for all knowledge tests is 80%" (Section 1, p.1-2); General Knowledge test is 50 questions / 40 correct (80%), confirmed via multiple third-party AK CDL prep sources against the federally standardized 49 CFR 383.135(a) minimum. No official time limit found; 60 minutes is a generous stand-in per this project''s convention.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('az_cdl', 'Commercial Driver (CDL)', 'AZ', 'Arizona CDL', 1, 1, 50, 3600, 80, 40, 'Arizona uses the AAMVA CDL Testing System (2005/2022 CDL Testing System manual, ADOT Motor Vehicle Division, Revised 01/2026). The manual explicitly states "The applicant must answer at least 80 percent of the questions correctly on each knowledge test to achieve a passing score" (Customer Service Guide for Commercial Drivers, p. 9). Exact question count (50) is not spelled out in the manual text itself but matches the federally standardized 49 CFR 383.135(a) General Knowledge format and is corroborated by multiple third-party AZ CDL prep sources (epermittest.com, dmv-written-test.com); no official time limit found, 60 minutes is a generous stand-in per this project''s convention.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ar_cdl', 'Commercial Driver (CDL)', 'AR', 'Arkansas CDL', 1, 1, 50, 3600, 80, 40, '', 1788111262);
