INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('tn_cdl', 'Commercial Driver (CDL)', 'TN', 'Tennessee CDL', 1, 1, 50, 3600, 80, 40, '', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('ut_cdl', 'Commercial Driver (CDL)', 'UT', 'Utah CDL', 1, 1, 50, 3600, 80, 40, 'Utah''s own manual (Driver License Division) and dld.utah.gov never disclose a General Knowledge item count or passing-score percentage anywhere -- confirmed via exhaustive search of both, same situation as this project''s Montana/Louisiana/New Mexico CDL tracks. 50Q/80%/40 correct is the AAMVA-standard convention (federally mandated 80% min under 49 CFR 383.135(a)) used as a stand-in per this project''s convention for hedged-mechanics CDL states; confirmed Utah-specific facts (30Q hazmat/20Q tank endorsement tests, 8/30 error-point skills thresholds) are documented in the track''s handbookNote instead, not modeled as separate exam configs here.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('vt_cdl', 'Commercial Driver (CDL)', 'VT', 'Vermont CDL', 1, 1, 50, 3600, 80, 40, 'Vermont''s CDL Manual (VN-111) never discloses a knowledge-test item count or passing-score percentage anywhere in its text -- confirmed via exhaustive search, same situation as this project''s Montana/Louisiana/New Mexico/Oregon/Utah CDL tracks. 50Q/80%/40 correct is the AAMVA-standard convention (federally mandated 80% min under 49 CFR 383.135(a)) used as a stand-in per this project''s convention for hedged-mechanics CDL states.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('wi_cdl', 'Commercial Driver (CDL)', 'WI', 'Wisconsin CDL', 1, 1, 50, 3600, 80, 40, 'Wisconsin''s Commercial Driver''s Manual (May 2026 edition, WisDOT) never discloses a General Knowledge item count or passing-score percentage anywhere -- the only official Wisconsin document stating an explicit 80% figure (WisDOT CDL Instructor Guidelines) applies to the separate CDL instructor licensing exam, not the driver knowledge test. 50Q/80%/40 correct is the AAMVA-standard convention (federally mandated 80% min under 49 CFR 383.135(a)) used as a stand-in per this project''s convention for hedged-mechanics CDL states.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('wv_cdl', 'Commercial Driver (CDL)', 'WV', 'West Virginia CDL', 1, 1, 50, 3600, 80, 40, 'West Virginia''s CDL Manual (WV DMV Rev. 08/2023 front matter over AAMVA base manual) confirms only the 80% passing score explicitly ("must be taken and passed, with at least an 80% score") -- no exact knowledge-test item count is disclosed anywhere in the manual, same situation as this project''s Montana/Louisiana/New Mexico/Oregon/Utah/Vermont CDL tracks. 50Q/80%/40 correct is the AAMVA-standard convention (federally mandated 80% min under 49 CFR 383.135(a)) used as a stand-in per this project''s convention for hedged-mechanics CDL states.', 1788111262);
INSERT INTO track_registry (exam_type, kind, state_code, short_name, active, is_exam_required, exam_question_count, exam_duration_sec, pass_percent, min_correct, mechanics_note, updated_at) VALUES ('wy_cdl', 'Commercial Driver (CDL)', 'WY', 'Wyoming CDL', 1, 1, 50, 3600, 80, 40, 'Wyoming''s CDL Manual ("Rules of the Road," Oct 2024) confirms the 80% passing score directly in its Wyoming-specific front matter ("the passing score for a written test is 80 percent"), independently re-confirmed on WYDOT''s live CDL Testing webpage -- but no exact per-test item count is disclosed anywhere. 50Q/80%/40 correct is the AAMVA-standard convention (federally mandated 80% min under 49 CFR 383.135(a)) used as a stand-in per this project''s convention for hedged-mechanics CDL states.', 1788111262);
